{
  "name": "pairwise_cost_gap_loss",
  "intuition": "This loss encourages the model to produce pairs where the higher-quality sample (lower cost) is assigned higher probability. By focusing on the cost gap, it directly penalizes pairs where the ordering is incorrect, which aligns with minimizing cost differences and improves preference consistency.",
  "pseudocode": "loss = mean over pairs of [-logsigmoid(log_prob_w - log_prob_l + cost_gap)]",
  "hyperparams": {
    "paradigm_family": "preference",
    "signal_family": "cost",
    "link_family": "pairwise",
    "agg_family": "mean",
    "constraint_family": "monotonic"
  },
  "operators_used": ["logsigmoid"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    log_prob_w = batch['log_prob_w']\n    log_prob_l = batch['log_prob_l']\n    weight = batch['weight']\n    cost_gap = batch.get('cost_gap', ops.zeros_like(log_prob_w))\n    diff = ops.sub(log_prob_w, log_prob_l)\n    scaled_diff = ops.add(diff, cost_gap)\n    loss_per_pair = -ops.logsigmoid(scaled_diff)\n    weighted_loss = ops.mul(loss_per_pair, weight)\n    return ops.mean(weighted_loss)"
}

