{
  "name": "loss_rankgap_tanh_advantage",
  "intuition": "Shift from margin-based pairwise losses to a rank-gap paradigm by leveraging the advantage difference between winners and losers, using a smooth tanh link to stabilize gradients and emphasize relative preference strength.",
  "pseudocode": "adv_gap = advantage_w - advantage_l\nscore_diff = clamp(lp_w - lp_l, -10, 10)\nloss = mean((1 - tanh(score_diff)) * (1 - tanh(adv_gap)) * weight)",
  "hyperparams": {
    "paradigm_family": "pairwise_rankgap",
    "signal_family": "advantage_gap",
    "link_family": "tanh",
    "agg_family": "mean",
    "constraint_family": "clamp_stabilized"
  },
  "operators_used": ["tanh", "clamp", "mean", "sub", "mul", "add"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', ops.ones_like(lpw))\n    adv_w = batch['advantage_w']\n    adv_l = batch['advantage_l']\n    score_diff = ops.clamp(lpw - lpl, -10.0, 10.0)\n    adv_gap = adv_w - adv_l\n    # Invert tanh to penalize low score difference and low advantage gap\n    loss_per_pair = (1 - ops.tanh(score_diff)) * (1 - ops.tanh(adv_gap))\n    loss_per_pair = loss_per_pair * weight\n    return ops.mean(loss_per_pair)"
}

