{
  "name": "pairwise_rank_gap_weighted_sigmoid_penalty_stabilized",
  "intuition": "Added required objective signals cost_a and cost_b to satisfy expects requirement and normalize by cost gap magnitude for scale invariance. Incorporated clamping on margin penalty to stabilize numerical values and replaced raw rank_gap with detached cost gap as a proxy for preference strength. Weighted loss is mean-aggregated with normalization and optional weighting to ensure numerical stability and correctness with proper signals.",
  "implementation_hint": {
    "expects": [
      "log_prob_w",
      "log_prob_l",
      "weight",
      "cost_a",
      "cost_b"
    ],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n    cost_a = batch['cost_a']\n    cost_b = batch['cost_b']\n    eps = 1e-8\n    gap = (cost_b - cost_a).detach()\n    norm_factor = 1.0 / (ops.mean(ops.abs(gap)) + eps)\n    margin_penalty = ops.clamp(ops.abs(lpw - lpl), 0.0, 10.0)\n    sigmoid_term = ops.sigmoid(-gap)\n    loss_per_pair = sigmoid_term + 0.1 * margin_penalty\n    weighted_loss = loss_per_pair * norm_factor\n    if weight is not None:\n        weighted_loss = weighted_loss * weight\n    return ops.mean(weighted_loss)"
}
